<?php
namespace WPKit\SiteDoctor\Scanners; use WPKit\SiteDoctor\{SiteDoctorIssue,SiteDoctorScanner}; if(!defined('ABSPATH'))exit;
final class PerformanceScanner implements SiteDoctorScanner{public function id():string{return 'performance';}public function label():string{return 'Performance';}public function scan():array{$o=[];$home=home_url('/');$r=wp_safe_remote_get($home,['timeout'=>10]);if(is_wp_error($r))return $o;$size=strlen(wp_remote_retrieve_body($r));if($size>2000000)$o[]=$this->i('large-html','performance','medium','review_required','Large homepage HTML payload','The homepage HTML is larger than 2 MB.','Review page-builder output, inline assets and third-party markup.');if(!wp_get_environment_type()){}$plugins=get_plugins();$perf=['litespeed-cache','wp-rocket','autoptimize','w3-total-cache'];$found=[];foreach($plugins as $file=>$p){$slug=strtolower($p['TextDomain']??'');$name=strtolower($p['Name']??'');foreach($perf as $x)if(strpos($slug,$x)!==false||strpos($name,str_replace('-',' ',$x))!==false)$found[]=$x;}if($found){}else $o[]=$this->i('no-cache-plugin-detected','performance','low','review_required','No recognized page-cache plugin detected','WP Kit did not detect one of the supported page-cache plugins.','Review server-level caching and hosting configuration; a cache plugin is not mandatory.');return $o;}private function i($id,$c,$s,$r,$t,$d,$rec){return new SiteDoctorIssue(['id'=>$id,'category'=>$c,'severity'=>$s,'risk'=>$r,'title'=>$t,'description'=>$d,'recommendation'=>$rec]);}}
